const cfg = {};
$('Read Run_Config').all().forEach((i) => { if (i.json.Setting) cfg[String(i.json.Setting).trim()] = i.json.Value; });
const limit = parseInt(cfg.Contacts_Per_Run, 10) || 5;

const clean = (s) => String(s || '').toLowerCase().replace(/\b(ltd|limited|the)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();

const approved = $('Read Opening_Candidates').all()
  .map((i) => i.json)
  .filter((r) =>
    r.Candidate_ID &&
    String(r.Review_Status || '').trim() === 'Approved' &&
    String(r.Processed || '').trim().toLowerCase() !== 'yes' &&
    String(r.Business_Name || '').trim() !== ''
  );

const seenVenue = new Set();
const out = [];
for (const r of approved) {
  const key = [r.Business_Name, r.City, r.Location].map(clean).join('|');
  if (seenVenue.has(key)) continue; // ek run mein ek venue sirf ek baar
  seenVenue.add(key);
  out.push({
    json: {
      Candidate_ID: r.Candidate_ID,
      Business_Name: String(r.Business_Name).trim(),
      City: r.City || '',
      Business_Type: r.Keyword || '',
      Location: r.Location || '',
      Opening_Status: String(r.Mode || '').trim() === 'Upcoming' ? 'Upcoming' : 'Recently Opened',
      Opening_Date: r.Opening_Date || '',
      Source_URL: r.Source_URL || '',
    },
  });
  if (out.length >= limit) break;
}
return out;

const ctx = $('Pick Approved').item.json;
const results = ($json && $json.organic_results) || [];

// Directory / social / news sites official website nahi hoti
const blocked = [
  'facebook.com', 'instagram.com', 'linkedin.com', 'tiktok.com', 'twitter.com', 'x.com', 'youtube.com',
  'tripadvisor.com', 'tripadvisor.co.uk', 'yelp.com', 'yelp.co.uk', 'trustpilot.com', 'wikipedia.org',
  'checkatrade.com', 'yell.com', 'pinterest.com', 'reddit.com', 'eventbrite.co.uk', 'ubereats.com',
  'deliveroo.co.uk', 'just-eat.co.uk', 'bbc.co.uk', 'bbc.com', 'gumtree.com', 'rightmove.co.uk',
  'zoopla.co.uk', 'linktr.ee', 'nhs.uk', 'gov.uk', 'google.com', 'google.co.uk',
];
const hostOf = (u) => { try { return new URL(u).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; } };
const isBlocked = (h) => !h || blocked.some((d) => h === d || h.endsWith('.' + d));

let website = '';
for (const o of results) {
  const h = hostOf(o.link);
  if (!isBlocked(h)) { website = new URL(o.link).origin; break; }
}
return { json: { ...ctx, website } };

const ctx = $('Pick Website').item.json;
const raw = $json.data;
const html = typeof raw === 'string' ? raw : '';
let contactUrl = '';

if (ctx.website && html) {
  const base = new URL(ctx.website);
  const re = /href=["']([^"'#]*contact[^"'#]*)["']/gi;
  let m;
  while ((m = re.exec(html))) {
    if (/^(mailto:|tel:)/i.test(m[1])) continue;
    try {
      const u = new URL(m[1], ctx.website);
      if (u.hostname === base.hostname) { contactUrl = u.href; break; }
    } catch (e) { /* ignore */ }
  }
}
return { json: { ...ctx, contactUrl } };

const ctx = $('Find Contact Page').item.json;
const homeRaw = $('Fetch Homepage').item.json.data;
const home = typeof homeRaw === 'string' ? homeRaw : '';
const contact = typeof $json.data === 'string' ? $json.data : '';
const today = new Date().toISOString().slice(0, 10);

const clean = (s) => String(s || '').toLowerCase().replace(/\b(ltd|limited|the)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
const visible = (h) => h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');

// 1) Website identity check: homepage par business ka naam milna chahiye
const nameClean = clean(ctx.Business_Name);
const tokens = nameClean.split(' ').filter((t) => t.length > 2);
const homeText = clean(visible(home));
const identity = !!(ctx.website && home && nameClean && (homeText.includes(nameClean) || (tokens.length > 0 && tokens.every((t) => homeText.includes(t)))));

// 2) Public contacts nikaalo (sirf identity confirm ho to)
const host = ctx.website ? new URL(ctx.website).hostname.replace(/^www\./, '') : '';
const findEmails = (h) => {
  const list = [];
  (h.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).forEach((e) => {
    e = e.toLowerCase();
    if (/\.(png|jpe?g|gif|webp|svg|css|js)$/.test(e)) return;
    if (/(example|sentry|wixpress|domain\.com|yourdomain|email\.com)/.test(e)) return;
    if (!list.includes(e)) list.push(e);
  });
  return list;
};
const findPhones = (h) => {
  const list = [];
  const seen = [];
  const add = (p) => {
    const digits = String(p).replace(/\D/g, '');
    if (digits.length < 10 || digits.length > 13 || seen.includes(digits)) return;
    seen.push(digits);
    list.push(String(p).trim());
  };
  (h.match(/href=["']tel:([^"']+)["']/gi) || []).forEach((m) => {
    let v = m.replace(/href=["']tel:/i, '').replace(/["']$/, '');
    try { v = decodeURIComponent(v); } catch (e) { /* keep raw */ }
    add(v);
  });
  (visible(h).match(/(?:\+44\s?\(?0?\)?\s?|\b0)\d[\d\s\-()]{8,12}\d/g) || []).forEach(add);
  return list;
};

let email = '', phone = '', form = '';
if (identity) {
  const emails = [...findEmails(contact), ...findEmails(home)];
  email = emails.find((e) => host && e.endsWith(host)) || emails[0] || '';
  phone = [...findPhones(contact), ...findPhones(home)][0] || '';
  form = ctx.contactUrl && /<form/i.test(contact) ? ctx.contactUrl : '';
}

// 3) Lead_Status
let status;
if (!ctx.website) status = 'Needs_Contact';
else if (!identity) status = 'Needs_Check';
else if (email || phone || form) status = 'Ready';
else status = 'Needs_Contact';

// Upcoming ki date guzar chuki ho to fresh confirmation chahiye
if (ctx.Opening_Status === 'Upcoming' && ctx.Opening_Date) {
  const d = new Date(ctx.Opening_Date);
  if (!isNaN(d) && d < new Date(today)) status = 'Needs_Check';
}

// 4) Venue-level duplicate: purana record ho to blank se overwrite nahi hoga
const key = [ctx.Business_Name, ctx.City, ctx.Location].map(clean).join('|');
const ex = $('Read Business_Leads').all().map((i) => i.json).find((r) => r.Venue_Key && r.Venue_Key === key) || null;
const pick = (n, o) => (n !== undefined && n !== null && String(n).trim() !== '' ? n : (o || ''));
if (ex && ex.Lead_Status === 'Ready' && status === 'Needs_Contact') status = 'Ready';

return {
  json: {
    Business_Name: pick(ctx.Business_Name, ex && ex.Business_Name),
    City: pick(ctx.City, ex && ex.City),
    Business_Type: pick(ctx.Business_Type, ex && ex.Business_Type),
    Location: pick(ctx.Location, ex && ex.Location),
    Opening_Status: pick(ctx.Opening_Status, ex && ex.Opening_Status),
    Opening_Date: pick(ctx.Opening_Date, ex && ex.Opening_Date),
    Website: pick(ctx.website, ex && ex.Website),
    Email: pick(email, ex && ex.Email),
    Phone: pick(phone, ex && ex.Phone),
    Contact_Form_URL: pick(form, ex && ex.Contact_Form_URL),
    Source_URL: ex && ex.Source_URL ? ex.Source_URL : (ctx.Source_URL || ''),
    Lead_Status: status,
    Last_Checked: today,
    Venue_Key: key,
  },
};

return $('Pick Approved').all().map((i) => ({
  json: { Candidate_ID: i.json.Candidate_ID, Processed: 'Yes' },
}));
